import { format, resolveConfig } from "prettier";
import { LOOKS } from "./looks";

const FAMILIES = ["technical", "film", "commercial", "music-video"] as const;

function signed(n: number) {
  return `${n >= 0 ? "+" : ""}${n.toFixed(2)}`;
}

/** docs/library/looks.md: the Looks & colour section of the library, generated from src/lib/colour/looks.ts. */
export function looksDoc(): string {
  const lines = [
    "# Looks & colour",
    "",
    "Generated by `pnpm colour:looks --write-doc` from `src/lib/colour/looks.ts`; do not edit by hand.",
    "",
    "Colour looks are grade files, not Remotion blocks: `colour:looks` applies them to footage with skin held and gated, `colour:grade` renders one, and `FilmFinish` (the `finish` column) adds grain, halation and bloom in the composition. Mood is valence and arousal on -1..1 by convention (brightness and warmth raise valence; saturation and contrast raise arousal), from colour-patch studies, not a measured emotion. Previews are on a synthetic test card: grey ramp, two hue sweeps, six skin tones on the skin line and four memory colours (sky, foliage, brand red, white).",
    "",
    "![Looks 1-6 on the test card](previews/colour-looks-1.jpg)",
    "",
    "![Looks 7-12 on the test card](previews/colour-looks-2.jpg)",
    "",
    "| Workflow | Command |",
    "|---|---|",
    "| Profile a reference into per-shot targets (colour script) | `pnpm colour:target --input <reference> --output <dir>` |",
    "| Shortlist looks for its mood | `pnpm colour:looks --target <dir>/target.json --input <video> --output <dir>` |",
    '| Plan a mood per shot and solve bounded grades | `pnpm colour:target --input <video> --mood "0:-0.6,0.1;12.4:-0.4,0.3" --output <dir>` |',
    "| Import a licensed LUT, then try it as a look | `pnpm colour:lut --add <file> --licence <id> --source <url> --project <id>` |",
    "| Hold the final film to the target | `pnpm colour:check --target <dir>/target.json --input <graded> --source <ungraded>` |",
    "",
  ];
  for (const family of FAMILIES) {
    const looks = LOOKS.filter((look) => look.family === family);
    if (!looks.length) continue;
    lines.push(`## ${family}`, "");
    lines.push("| Look | Mood v / a | Palette | Finish | Skin | Intent | Risks |", "|---|---|---|---|---|---|---|");
    for (const look of looks) {
      const palette = `${look.palette.scheme}${look.palette.keyHues.length ? `: ${look.palette.keyHues.join(", ")}` : ""}`;
      const skin = `${look.skin.mode}, chroma ×${look.skin.chroma}, hue ±${look.skin.hueAllowance}°`;
      lines.push(
        `| \`${look.id}\` ${look.name} | ${signed(look.mood.valence)} / ${signed(look.mood.arousal)} | ${palette} | ${look.finish} | ${skin} | ${look.intent} | ${look.risks.join("; ")} |`,
      );
    }
    lines.push("");
  }
  return `${lines.join("\n").trimEnd()}\n`;
}

/** The doc as the repository's Prettier writes it, so the checked-in file and the generator agree. */
export async function formatMarkdown(markdown: string, file: string): Promise<string> {
  return format(markdown, { ...(await resolveConfig(file)), parser: "markdown" });
}
